let advertShift=0;
function advertsForYear(y=Number(year())){return eraAdverts.filter(a=>a.from<=y&&a.to>=y);}
function advertArt(a){return `<span class="ad-object ad-object-${a.art}" aria-hidden="true"><i></i><b>${a.art==='phone'?'NOKIA':a.art==='mp3'?'128 MB':a.art==='card'?'GAME':a.art==='pager'?'138 001':a.art==='sms'?'♪':a.art==='letter'?'寄给未来':a.art==='camera'?'3.2M':'OLDDAYS'}</b><em></em></span>`;}
function eraAdvertMarkup(slot='banner',offset=0){const ads=advertsForYear();const a=ads[(advertShift+offset)%ads.length]||eraAdverts[0];return `<button class="era-advert ad-${a.tone} ad-slot-${slot}" data-advert="${a.id}" aria-label="年代广告：${escapeHTML(a.title)}"><span class="ad-written"><small>${escapeHTML(a.kicker)}</small><strong>${escapeHTML(a.title)}</strong><span>${escapeHTML(a.copy)}</span><em>${escapeHTML(a.foot)}</em></span>${advertArt(a)}<span class="ad-disclosure">怀旧创作广告 · 非历史原稿</span></button>`;}
function openAdvert(id){const ad=eraAdverts.find(a=>a.id===id);if(!ad)return;dialog('年代广告 · '+ad.title,`<div class="ad-detail">${eraAdvertMarkupById(ad)}<p>这是一张按年代气氛创作的广告，不是品牌官方广告，也不代表真实套餐、价格或活动。</p><div class="ad-detail-actions"><button class="primary" data-ad-sms="${ad.code}">在旧手机里发送体验代码</button><button data-phone-lab>进入复古手机</button></div><p class="scene-note">所有短信操作均在本机模拟，106XXXX 是占位符，不会发送真实短信或产生费用。</p></div>`);}
function eraAdvertMarkupById(ad){return `<div class="era-advert ad-${ad.tone} ad-slot-poster"><span class="ad-written"><small>${escapeHTML(ad.kicker)}</small><strong>${escapeHTML(ad.title)}</strong><span>${escapeHTML(ad.copy)}</span><em>${escapeHTML(ad.foot)}</em></span>${advertArt(ad)}<span class="ad-disclosure">怀旧创作广告 · 非历史原稿</span></div>`;}
function renderAdMagazine(){return `<section class="ad-magazine"><header><small>OLDDAYS / BACK COVER COLLECTION</small><h1>${year()} · 翻到杂志的最后一页</h1><p>手机铃声、壁纸、数码产品、游戏点卡……那些密密麻麻的广告，也是一种时代记忆。</p></header><nav><button data-action="home">返回首页</button><button data-phone-lab>进入旧手机</button><button data-cycle-ads>换一组广告</button></nav><div class="printed-magazine"><img src="images/posters/magazine.jpg" alt="掌中时代原创怀旧杂志封底"><div><h2>这才是书背后那一页。</h2><p>彩铃、壁纸、MP3、游戏攻略，密密麻麻挤在一起的掌中世界。</p><button data-ad-sms="铃声01">编辑 铃声01 → 106XXXX</button><button data-phone-gallery>去手机里挑张图片</button><button data-poster-room>翻看更多海报</button><small>AI辅助怀旧创作，非历史原刊；号码为本机演示占位符。</small></div></div><div class="magazine-ad-grid">${advertsForYear().map(ad=>`<article>${eraAdvertMarkupById(ad)}<button data-ad-sms="${ad.code}">编辑「${escapeHTML(ad.code)}」发到 106XXXX</button></article>`).join('')}</div><aside class="sms-classified"><h2>个性手机 DIY · 体验代码表</h2><p>铃声01 · 原创8位旋律　｜　壁纸01 · 蓝色星空　｜　游戏01 · 贪吃蛇</p><p>编辑代码，发送到 <b>106XXXX</b>（本机演示）</p><p>原创怀旧创作，非历史服务。发送和回复都发生在本设备，不联网发短信、不订阅、不收费。</p></aside></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-advert],[data-ad-sms],[data-cycle-ads],[data-ad-magazine]');if(!b)return;e.preventDefault();if(b.dataset.advert)openAdvert(b.dataset.advert);else if(b.dataset.adSms){smsView='compose';$('#modal').close();phoneState.app='sms';phoneState.draft=b.dataset.adSms;openPhoneLab();}else if(b.hasAttribute('data-cycle-ads')){advertShift++;if(current.type==='admagazine')navigate(current,false);else if(current.type==='home')navigate(current,false);}else {$('#modal').close();navigate({type:'admagazine',name:'年代杂志封底',url:'archaeo://ads'});}});
